from math import comb

def eulerian_num(n, m):
    # Helper function to compute binomial coefficient
    def binom_coeff(n, k):
        return comb(n, k)

    # The Eulerian number A(n, m) can be computed using the formula:
    # A(n, m) = (m+1) * A(n-1, m) + (n-m) * A(n-1, m-1)
    # with base cases A(0, 0) = 1 and A(n, 0) = n for n >= 0

    if n == m:
        return 1
    elif m == 0:
        return n
    else:
        return (m + 1) * eulerian_num(n - 1, m) + (n - m) * eulerian_num(n - 1, m - 1)

