def search(arr):
    n = len(arr)

    # Helper function to find the unique element
    def find_unique(left, right):
        if left == right:
            return arr[left]

        mid = (left + right) // 2

        # If mid is the unique element
        if (mid == 0 or arr[mid] != arr[mid - 1]) and (mid == n - 1 or arr[mid] != arr[mid + 1]):
            return arr[mid]

        # If the left half is sorted
        if arr[left] == arr[mid]:
            return find_unique(mid + 1, right)

        # If the right half is sorted
        return find_unique(left, mid - 1)

    return find_unique(0, n - 1)

