def sum_common_divisors(a, b):
    def gcd(x, y):
        while y != 0:
            (x, y) = (y, x % y)
        return x

    def sum_divisors(n):
        total = 0
        for i in range(1, n + 1):
            if n % i == 0:
                total += i
        return total

    # Find GCD of a and b
    gcd_ab = gcd(a, b)

    # Calculate sum of divisors of GCD(a, b)
    return sum_divisors(gcd_ab)

